const grid=document.querySelector('#project-grid');
function card(p,i){return `<a class="project" href="#project-${i+1}" aria-label="查看 ${p.cn}"><div class="card-anchor"><div class="card-motion"><div class="card-reveal" style="--order:${i}"><div class="card-device"><div class="card-device-top" aria-hidden="true"><i></i><span></span></div><div class="card-visual" style="--tone:${p.tone}">${p.video?`<video class="project-preview" data-preview-base="${p.image.replace('poster.jpg','preview-')}" muted playsinline loop preload="none" poster="${p.image}" aria-label="${p.title} ${p.tag==='TECHNICAL ART'?'水体效果预览':p.tag==='3D ENVIRONMENT'?'场景展示预览':'游戏流程预览'}"></video>`:`<img src="${p.image}" alt="${p.cn}的示例视觉图片" width="600" height="660" ${i>2?'loading="lazy"':''}>`}</div><div class="card-device-bottom" aria-hidden="true"><i></i></div></div></div></div></div><div class="project-copy"><div><h2>${p.title}</h2><p>${p.desc||'&nbsp;'}</p><div class="card-tags">${(p.tags||[p.tag]).map(t=>`<span>${t}</span>`).join('')}</div></div><span class="project-link">${String(i+1).padStart(2,'0')} / Exploration <b>↗</b></span></div></a>`}
grid.innerHTML=projects.map(card).join('');
